const LEGAL_SUFFIXES = [
  'private limited', 'pvt ltd', 'pvt', 'pte ltd', 'llp', 'llc',
  'incorporated', 'inc', 'technologies', 'technology', 'labs',
  'corporation', 'corp', 'limited', 'ltd', 'gmbh'
];

const SENIORITY_NOISE = [
  'senior', 'sr', 'junior', 'jr', ' ii', ' iii', ' iv', 'lead', 'principal'
];

const LOCATION_ALIASES = {
  'bengaluru': 'bangalore', 'blr': 'bangalore',
  'gurgaon': 'gurugram',
  'delhi': 'delhi ncr', 'new delhi': 'delhi ncr', 'ncr': 'delhi ncr',
  'bombay': 'mumbai',
  'madras': 'chennai',
  'poona': 'pune'
};

function normCompany(raw) {
  let s = (raw || '').toLowerCase().trim();
  s = s.replace(/[.,]/g, '');
  for (const suffix of LEGAL_SUFFIXES) {
    const re = new RegExp('\\b' + suffix + '\\b', 'g');
    s = s.replace(re, '');
  }
  return s.replace(/\s+/g, ' ').trim();
}

function normRole(raw) {
  let s = (raw || '').toLowerCase().trim();
  s = s.replace(/\(.*?\)/g, '');
  s = s.replace(/#\w+/g, '');
  s = s.replace(/\breq[-\s]?\d+\b/g, '');
  for (const noise of SENIORITY_NOISE) {
    s = s.split(noise).join(' ');
  }
  s = s.replace(/[.,]/g, '');
  return s.replace(/\s+/g, ' ').trim();
}

function normLocation(raw) {
  let s = (raw || '').toLowerCase().trim();
  s = s.replace(/[.,]/g, '');
  s = s.replace(/\s+/g, ' ').trim();
  if (LOCATION_ALIASES[s]) return LOCATION_ALIASES[s];
  for (const alias of Object.keys(LOCATION_ALIASES)) {
    if (s.includes(alias)) return LOCATION_ALIASES[alias];
  }
  return s;
}

const results = [];
for (const item of $input.all()) {
  const j = item.json;
  const nc = normCompany(j.company);
  const nr = normRole(j.role);
  const nl = normLocation(j.location);
  const normDescription = (j.description || '').toLowerCase().replace(/\s+/g, ' ').trim().slice(0, 4000);

  results.push({
    json: {
      ...j,
      norm_company: nc,
      norm_role: nr,
      norm_location: nl,
      norm_description: normDescription,
      exact_key_input: nc + '|' + nr + '|' + nl,
      content_key_input: normDescription
    }
  });
}
return results;

return $input.all().map(item => {
  const j = item.json;
  return {
    json: {
      id: j.id,
      content_hash: j.content_hash,
      source_id: j.source_id || null,
      company: j.company,
      role: j.role,
      location: j.location || null,
      employment_type: j.employment_type || null,
      apply_url: j.apply_url,
      source: j.source,
      description: j.description || null,
      norm_company: j.norm_company,
      norm_description: j.norm_description,
      posted_date: j.posted_date || null
    }
  };
});
